const DB_NAME="my-state-local", DB_VERSION=6;
const STORES=["meds","mood","sleep","diary","traits","medLogs","criticality","goals","cycle","proscons","plannerLists"];
const PHASES=["depression","mixed","remission","hypomania","mania"];
const PHASE_LABELS={depression:"Депрессивная",mixed:"Смешанная",remission:"Ремиссия",hypomania:"Гипоманиакальная",mania:"Маниакальная"};
const MOOD_LABELS=["пропасть","очень тяжело","тяжело","нормально","хорошо","слишком хорошо"];
function moodLabel(score){return trUI(MOOD_LABELS[Number(score)]||"");}
let db,diaryRange=null,homeMoodInitialized=false;
function openDB(){return new Promise((resolve,reject)=>{const r=indexedDB.open(DB_NAME,DB_VERSION);r.onupgradeneeded=()=>{const d=r.result;for(const s of STORES)if(!d.objectStoreNames.contains(s))d.createObjectStore(s,{keyPath:"id",autoIncrement:true});};r.onsuccess=()=>resolve(r.result);r.onerror=()=>reject(r.error);});}
// Cycle records are mirrored in localStorage as a second persistence layer.
// Existing IndexedDB records are migrated once, so earlier entries are retained.
const CYCLE_LOCAL_KEY="my-state-cycle-records-v1";
function readCycleLocal(){try{const v=JSON.parse(localStorage.getItem(CYCLE_LOCAL_KEY)||"[]");return Array.isArray(v)?v.filter(x=>x&&typeof x==="object"):[];}catch{return [];}}
function writeCycleLocal(rows){try{localStorage.setItem(CYCLE_LOCAL_KEY,JSON.stringify(rows));return true;}catch(e){console.warn("Cycle local backup unavailable",e);return false;}}
function idbCycleRows(){return new Promise((resolve,reject)=>{try{const r=db.transaction("cycle","readonly").objectStore("cycle").getAll();r.onsuccess=()=>resolve(Array.isArray(r.result)?r.result:[]);r.onerror=()=>reject(r.error||new Error("Не удалось прочитать цикл из IndexedDB"));}catch(e){reject(e);}});}
function cycleRowsMerged(dbRows=[],localRows=readCycleLocal()){
 const map=new Map();for(const x of dbRows)if(x&&typeof x==="object")map.set(String(x.id),x);
 // localStorage is written synchronously before IndexedDB, so it wins on conflicts.
 for(const x of localRows)if(x&&typeof x==="object"&&x.id!=null)map.set(String(x.id),x);
 return [...map.values()];
}
async function initCycleStorage(){
 let dbRows=[];try{dbRows=await idbCycleRows();}catch(e){console.warn("Cycle IndexedDB read failed; using local copy",e);}
 const merged=cycleRowsMerged(dbRows,readCycleLocal());
 writeCycleLocal(merged);
 try{const tx=db.transaction("cycle","readwrite"),store=tx.objectStore("cycle");for(const row of merged)if(row.id!=null)store.put(row);await new Promise((resolve,reject)=>{tx.oncomplete=resolve;tx.onerror=()=>reject(tx.error);tx.onabort=()=>reject(tx.error||new Error("Cycle migration aborted"));});}catch(e){console.warn("Cycle IndexedDB migration skipped; local copy retained",e);}
}
async function all(store){if(store==="cycle"){
  let rows=[];try{rows=await idbCycleRows();}catch(e){console.warn("Cycle IndexedDB unavailable; reading local copy",e);}
  const merged=cycleRowsMerged(rows,readCycleLocal());
  try{writeCycleLocal(merged);}catch(e){console.error("Cycle local mirror write failed",e);}
  return merged.sort((a,b)=>String(b.created||"").localeCompare(String(a.created||"")));
 }
 return new Promise((resolve,reject)=>{const r=db.transaction(store,"readonly").objectStore(store).getAll();r.onsuccess=()=>resolve((r.result||[]).sort((a,b)=>(b.created||"").localeCompare(a.created||"")));r.onerror=()=>reject(r.error);});}
async function add(store,v){if(store==="cycle"){
 const rows=await all("cycle"),id=Math.max(0,...rows.map(x=>Number(x.id)||0))+1,row={...v,id,created:new Date().toISOString()};
 const localSaved=writeCycleLocal([...rows,row]);
 try{const tx=db.transaction("cycle","readwrite");tx.objectStore("cycle").put(row);await new Promise((resolve,reject)=>{tx.oncomplete=resolve;tx.onerror=()=>reject(tx.error);tx.onabort=()=>reject(tx.error||new Error("Cycle save aborted"));});}catch(err){console.warn("Cycle IndexedDB save failed",err);if(!localSaved)throw new Error("Браузер не смог сохранить данные ни в IndexedDB, ни в localStorage");}
 return id;
 }
 return new Promise((resolve,reject)=>{const tx=db.transaction(store,"readwrite"),r=tx.objectStore(store).add({...v,created:new Date().toISOString()});let id;r.onsuccess=()=>{id=r.result;};tx.oncomplete=()=>resolve(id);tx.onerror=()=>reject(tx.error);tx.onabort=()=>reject(tx.error||new Error("Transaction aborted"));});}
async function put(store,v){if(store==="cycle"){
 const rows=await all("cycle"),i=rows.findIndex(x=>String(x.id)===String(v.id));if(i<0)rows.push(v);else rows[i]=v;const localSaved=writeCycleLocal(rows);
 try{const tx=db.transaction("cycle","readwrite");tx.objectStore("cycle").put(v);await new Promise((resolve,reject)=>{tx.oncomplete=resolve;tx.onerror=()=>reject(tx.error);tx.onabort=()=>reject(tx.error||new Error("Cycle update aborted"));});}catch(err){console.warn("Cycle IndexedDB update failed",err);if(!localSaved)throw new Error("Не удалось сохранить изменения");}return;
 }
 return new Promise((resolve,reject)=>{const tx=db.transaction(store,"readwrite");tx.objectStore(store).put(v);tx.oncomplete=resolve;tx.onerror=()=>reject(tx.error);});}
async function remove(store,id){if(store==="cycle"){
 const rows=await all("cycle"),localSaved=writeCycleLocal(rows.filter(x=>String(x.id)!==String(id)));
 try{const tx=db.transaction("cycle","readwrite");tx.objectStore("cycle").delete(Number(id));await new Promise((resolve,reject)=>{tx.oncomplete=resolve;tx.onerror=()=>reject(tx.error);tx.onabort=()=>reject(tx.error||new Error("Cycle delete aborted"));});}catch(err){console.warn("Cycle IndexedDB delete failed",err);if(!localSaved)throw new Error("Не удалось удалить запись");}return;
 }
 return new Promise((resolve,reject)=>{const tx=db.transaction(store,"readwrite");tx.objectStore(store).delete(Number(id));tx.oncomplete=resolve;tx.onerror=()=>reject(tx.error);});}

// User-created comparison themes and dated checklists are stored locally in IndexedDB.
let plannerMonth=new Date(new Date().getFullYear(),new Date().getMonth(),1);
const plannerLocale=()=>{const l=localStorage.getItem("my-state-language")||"ru";return l==="pl"?"pl-PL":l==="en"?"en-GB":"ru-RU";};
const plannerDateLabel=d=>new Date(d+"T12:00:00").toLocaleDateString(plannerLocale(),{day:"numeric",month:"long",year:"numeric"});
async function renderProsCons(){
 const rows=await all("proscons"),host=document.querySelector("#proscons-list");if(!host)return;
 host.innerHTML=rows.map(t=>`<article class="entry planner-entry"><details class="planner-details"><summary><strong>${esc(t.title)}</strong><span class="small muted">${(t.pros||[]).length} + · ${(t.cons||[]).length} −</span></summary><div class="proscons-columns"><section><h4>Плюсы</h4><div>${(t.pros||[]).map((v,i)=>`<div class="planner-line"><span>${esc(v)}</span><button type="button" class="text-button" data-pc-edit="${t.id}|pros|${i}">Изменить</button><button type="button" class="delete" data-pc-del="${t.id}|pros|${i}">Удалить</button></div>`).join("")}</div><button type="button" class="secondary" data-pc-add="${t.id}|pros">＋ Добавить плюс</button></section><section><h4>Минусы</h4><div>${(t.cons||[]).map((v,i)=>`<div class="planner-line"><span>${esc(v)}</span><button type="button" class="text-button" data-pc-edit="${t.id}|cons|${i}">Изменить</button><button type="button" class="delete" data-pc-del="${t.id}|cons|${i}">Удалить</button></div>`).join("")}</div><button type="button" class="secondary" data-pc-add="${t.id}|cons">＋ Добавить минус</button></section></div></details><div class="entry-actions"><button type="button" class="text-button" data-pc-rename="${t.id}">Переименовать</button><button type="button" class="delete" data-pc-delete="${t.id}">Удалить тему</button></div></article>`).join("")||'<p class="muted">Пока нет тем. Создай первую тему выше.</p>';
}
async function renderPlannerLists(){
 const rows=await all("plannerLists"),host=document.querySelector("#planner-lists");if(!host)return;
 host.innerHTML=rows.map(x=>`<article class="entry planner-entry"><details class="planner-details"><summary><strong>${esc(x.title)}</strong><span class="small muted">${x.due?plannerDateLabel(x.due):"Без даты"} · ${(x.items||[]).filter(i=>i.done).length}/${(x.items||[]).length}</span></summary><div class="planner-items">${(x.items||[]).map((it,i)=>`<div class="planner-item"><label class="planner-item-label"><input type="checkbox" data-plan-done="${x.id}|${i}" ${it.done?"checked":""}><span class="${it.done?"is-done":""}">${esc(it.text)}</span></label><button type="button" class="text-button" data-plan-edit="${x.id}|${i}">Изменить</button><button type="button" class="delete" data-plan-del="${x.id}|${i}">Удалить</button></div>`).join("")}</div><form class="planner-add-item" data-plan-add="${x.id}"><input name="text" required placeholder="Новая позиция"><button class="secondary">＋ Добавить</button></form></details><div class="entry-actions"><button type="button" class="text-button" data-plan-rename="${x.id}">Изменить список</button><button type="button" class="delete" data-plan-delete="${x.id}">Удалить список</button></div></article>`).join("")||'<p class="muted">Пока нет списков. Создай первый список выше.</p>';
}
function plannerCalendarHTML(year,month,rows){
 const first=new Date(year,month,1),offset=(first.getDay()+6)%7,days=new Date(year,month+1,0).getDate(),labels=["Пн","Вт","Ср","Чт","Пт","Сб","Вс"],has=new Set(rows.filter(x=>x.due).map(x=>x.due));let html=labels.map(x=>`<span class="planner-weekday">${x}</span>`).join("");
 for(let i=0;i<offset;i++)html+='<span class="planner-empty"></span>';
 for(let d=1;d<=days;d++){const key=`${year}-${String(month+1).padStart(2,"0")}-${String(d).padStart(2,"0")}`,today=key===localDate();html+=`<button type="button" class="planner-day ${today?"today":""} ${has.has(key)?"has-plans":""}" data-planner-day="${key}">${d}${has.has(key)?'<i></i>':""}</button>`;}
 return html;
}
async function renderPlannerCalendar(){const rows=await all("plannerLists"),y=plannerMonth.getFullYear(),m=plannerMonth.getMonth();document.querySelector("#planner-month").textContent=plannerMonth.toLocaleDateString(plannerLocale(),{month:"long",year:"numeric"});document.querySelector("#planner-calendar").innerHTML=plannerCalendarHTML(y,m,rows);}
async function openPlannerDay(day){const rows=(await all("plannerLists")).filter(x=>x.due===day);document.querySelector("#planner-day-title").textContent=`${trUI("Планы на день")}: ${plannerDateLabel(day)}`;const host=document.querySelector("#planner-day-content");host.innerHTML=rows.map(x=>`<details class="planner-day-list"><summary><strong>${esc(x.title)}</strong><span class="small muted">${(x.items||[]).filter(i=>i.done).length}/${(x.items||[]).length}</span></summary>${(x.items||[]).map((it,i)=>`<label class="planner-day-item"><input type="checkbox" data-plan-done="${x.id}|${i}" ${it.done?"checked":""}><span class="${it.done?"is-done":""}">${esc(it.text)}</span></label>`).join("")||'<p class="muted">В списке пока нет позиций.</p>'}</details>`).join("")||'<p class="muted">На этот день списков нет.</p>';document.querySelector("#planner-day-modal").hidden=false;}

function esc(v=""){return String(v??"").replace(/[&<>"']/g,c=>({"&":"&amp;","<":"&lt;",">":"&gt;",'"':"&quot;","'":"&#39;"}[c]));}
function fmt(v){const lang=localStorage.getItem("my-state-language")||"ru";const locale=lang==="pl"?"pl-PL":lang==="en"?"en-GB":"ru-RU";return v?new Date(v).toLocaleString(locale):"";}
function localDateTime(){const d=new Date();d.setMinutes(d.getMinutes()-d.getTimezoneOffset());return d.toISOString().slice(0,16);}
function localDate(){return localDateTime().slice(0,10);}
function formObject(f){return Object.fromEntries(new FormData(f).entries());}
function show(view){document.querySelectorAll(".view").forEach(x=>x.classList.toggle("active",x.id===`view-${view}`));document.querySelectorAll(".tab").forEach(x=>x.classList.toggle("active",x.dataset.view===view));({home:async()=>{await renderHomeMeds();await renderPlannerCalendar();},meds:renderMeds,mood:renderMood,sleep:renderSleep,cycle:renderCycle,diary:renderDiary,personality:renderTraits,criticality:renderIdeas,goals:renderGoals,proscons:renderProsCons,lists:renderPlannerLists})[view]?.();}
document.querySelectorAll("[data-view]").forEach(b=>b.addEventListener("click",()=>show(b.dataset.view)));
document.querySelectorAll("[data-go]").forEach(b=>b.addEventListener("click",()=>show(b.dataset.go)));
function card(title,sub,body,store,id){return `<article class="entry"><div class="entry-title">${esc(title)}</div><small>${esc(sub||"")}</small>${body||""}<div class="entry-actions"><button class="delete" data-delete="${store}:${id}">Удалить</button></div></article>`;}
document.addEventListener("click",async e=>{
 const del=e.target.closest("[data-delete]");if(del){const [st,id]=del.dataset.delete.split(":");if(confirm(trUI("Удалить эту запись?"))){await remove(st,id);refreshAll();}return;}
 const take=e.target.closest("[data-take]");if(take){const [medId,period]=take.dataset.take.split("|");await add("medLogs",{medId:Number(medId),period,date:localDate(),takenAt:new Date().toISOString()});renderMeds();renderHomeMeds();return;}
 const toggle=e.target.closest("[data-collapse]");if(toggle){const el=document.getElementById(toggle.dataset.collapse);if(el){el.hidden=!el.hidden;toggle.textContent=el.hidden?"Показать дни":"Свернуть дни";}return;}
 const assess=e.target.closest("[data-assess]");if(assess){const id=Number(assess.dataset.assess),wrap=document.querySelector(`#assessment-${id}`);if(wrap)wrap.hidden=!wrap.hidden;return;}
 const saveAssess=e.target.closest("[data-save-assess]");if(saveAssess){const id=Number(saveAssess.dataset.saveAssess),item=(await all("criticality")).find(x=>x.id===id),wrap=document.querySelector(`#assessment-${id}`);if(!item||!wrap)return;const value=wrap.querySelector("select").value;if(!value)return;const now=new Date(),day=localDate(),moods=await all("mood"),same=moods.filter(m=>(m.date||"").slice(0,10)===day&&m.phase).sort((a,b)=>(b.date||"").localeCompare(a.date||""));const history=[...(item.assessmentHistory||[]),{assessment:assessmentLabel(value),assessmentCode:value,date:now.toISOString(),phase:same[0]?.phase||"Фаза не указана"}];await put("criticality",{...item,assessment:value,assessedAt:now.toISOString(),assessmentPhase:same[0]?.phase||"",assessmentHistory:history});renderIdeas();await syncGoals();renderGoals();return;}
});
async function renderMeds(){const [items,logs]=await Promise.all([all("meds"),all("medLogs")]);document.querySelector("#med-list").innerHTML=items.map(m=>{const ml=logs.filter(l=>l.medId===m.id),dates=[...new Set([...ml.map(l=>l.date),localDate()])].sort().reverse(),active=(m.doses||[]).map(d=>d.period),bodyId=`med-days-${m.id}`;const rows=dates.map(date=>{const cells=["Утро","Обед","Вечер"].map(period=>{const n=ml.filter(l=>l.date===date&&l.period===period).length;const action=active.includes(period)&&date===localDate()?`<button class="secondary" data-take="${m.id}|${period}">Отметить</button>`:"·";return `<td>${n?`✓${n>1?` × ${n}`:""}<br>`:""}${action}</td>`}).join("");return `<tr><td>${esc(date)}</td>${cells}</tr>`}).join("");return `<article class="entry"><div class="entry-title">${esc(m.name)} · ${esc(m.doseMg??"—")} мг</div><small>${(m.doses||[]).map(d=>esc(d.period)).join(", ")} · ${(m.doses||[]).length} приём(а) в день</small><p><button class="text-button" data-collapse="${bodyId}">Показать дни</button></p><div id="${bodyId}" class="table-wrap" hidden><table><thead><tr><th>Дата</th><th>Утро</th><th>Обед</th><th>Вечер</th></tr></thead><tbody>${rows||`<tr><td colspan="4">Отметок пока нет</td></tr>`}</tbody></table></div><div class="entry-actions"><button class="delete" data-delete="meds:${m.id}">Удалить препарат</button></div></article>`}).join("")||"<p class='muted'>Препаратов пока нет.</p>";}
async function renderHomeMeds(){
 const [items,logs,moods,cycle]=await Promise.all([all("meds"),all("medLogs"),all("mood"),all("cycle")]);
 document.querySelector("#home-med-checks").innerHTML=items.map(m=>{const periods=(m.doses||[]).map(d=>d.period);return `<article class="entry"><b>${esc(m.name)} · ${esc(m.doseMg)} мг</b><div class="dose-grid">${periods.map(period=>{const n=logs.filter(l=>l.medId===m.id&&l.date===localDate()&&l.period===period).length;return `<div class="dose-status"><span>${esc(period)}</span><b>${n?`Отмечено: ${n}`:"Не отмечено"}</b><button class="secondary" data-take="${m.id}|${period}">${n?"Ещё раз":"Отметить"}</button></div>`}).join("")}</div></article>`}).join("")||"Препаратов пока нет.";
 const lastMood=moods.sort((a,b)=>String(b.date||"").localeCompare(String(a.date||"")))[0];const homeRange=document.querySelector("#home-mood-range");if(homeRange&&!homeMoodInitialized){if(lastMood&&Number.isFinite(Number(lastMood.score)))homeRange.value=String(lastMood.score);document.querySelector("#home-mood-value").textContent=`${homeRange.value} · ${moodLabel(homeRange.value)}`;const moodInput=document.querySelector("#mood-range");if(moodInput){moodInput.value=homeRange.value;updateMood();}homeMoodInitialized=true;}
 const info=cycleInfo(cycle),today=localDate(),lastStart=info.starts.filter(x=>x<=today).sort().at(-1),dayNo=lastStart?dayDiff(lastStart,today)+1:null,next=info.starts.length&&info.avg?dateKey(shiftDate(dateFromKey(info.starts.at(-1)),info.avg)):"",forecast=cycleForecast(info);const status=[];
 const phase=phaseForDate(today,info,forecast);
 status.push(`${trUI("Фаза цикла")}: ${phase?trUI(phase):trUI("Не определена")}`);
 status.push(`${trUI("День цикла")}: ${dayNo||trUI("Не определён")}`);
 const homeLocale=localStorage.getItem("my-state-language")==="pl"?"pl-PL":localStorage.getItem("my-state-language")==="en"?"en-GB":"ru-RU";status.push(`${trUI("Дата начала следующих месячных")}: ${next?dateFromKey(next).toLocaleDateString(homeLocale):trUI("Недостаточно данных")}`);
 document.querySelector("#home-cycle-info").innerHTML=status.map(x=>`<p>${esc(x)}</p>`).join("");
}
async function renderMood(){const a=await all("mood");document.querySelector("#mood-list").innerHTML=a.map(x=>card(`${x.score}/5 · ${moodLabel(x.score)}`,`${fmt(x.date)}${x.phase?" · Фаза: "+x.phase:" · Фаза не указана"}`,`<p>Гипервоодушевление: ${x.enthusiasm??0}/2</p><p>Раздражительность: ${x.irritability??0}/2</p><p>Пустота: ${x.emptiness??0}/2</p>${Object.entries(x.customIndicators||{}).map(([k,v])=>`<p>${esc(k)}: ${["Нет","Умеренно","Сильно"][Number(v)]}</p>`).join("")}${x.note?`<p>${esc(x.note)}</p>`:""}`,"mood",x.id)).join("")||"<p class='muted'>Оценок пока нет.</p>";renderCustomMoodFields();}

const MOOD_CUSTOM_KEY="my-state-custom-mood-indicators";
function customMoodNames(){try{return JSON.parse(localStorage.getItem(MOOD_CUSTOM_KEY)||"[]").filter(x=>typeof x==="string");}catch{return [];}}
function renderCustomMoodFields(){const host=document.querySelector("#mood-custom-fields");if(!host)return;host.innerHTML=customMoodNames().map((name,i)=>`<label>${esc(name)}: <strong id="custom-mood-value-${i}">0 · Нет</strong><input type="range" min="0" max="2" step="1" value="0" name="customMood_${i}" data-custom-mood="${i}"><span class="scale"><span>Нет</span><span>Умеренно</span><span>Сильно</span></span></label>`).join("");host.querySelectorAll("input[data-custom-mood]").forEach(r=>r.addEventListener("input",()=>{host.querySelector("#custom-mood-value-"+r.dataset.customMood).textContent=`${r.value} · ${["Нет","Умеренно","Сильно"][Number(r.value)]}`;}));}
document.querySelector("#add-mood-indicator").addEventListener("click",()=>{const name=prompt(trUI("Название собственного показателя:"));if(!name||!name.trim())return;const list=customMoodNames();if(list.some(x=>x.toLocaleLowerCase()===name.trim().toLocaleLowerCase())){alert(trUI("Такой показатель уже есть."));return;}list.push(name.trim());localStorage.setItem(MOOD_CUSTOM_KEY,JSON.stringify(list));renderCustomMoodFields();});
async function renderSleep(){const a=await all("sleep");document.querySelector("#sleep-list").innerHTML=a.map(x=>card("Сон",`${x.date} · ${x.bed}–${x.wake}`,`<p>${x.woke==="yes"?"Ночные пробуждения: "+(x.wakeIntervals||[]).map(t=>esc(t.from)+"–"+esc(t.to)).join(", "):"Ночных пробуждений не было"}</p>${x.dream?`<p><b>Описание сна:</b> ${esc(x.dream)}</p>`:""}`,"sleep",x.id)).join("")||"<p class='muted'>Записей о сне пока нет.</p>";}
async function renderDiary(){let a=await all("diary");if(diaryRange)a=a.filter(x=>x.date.slice(0,10)>=diaryRange.from&&x.date.slice(0,10)<=diaryRange.to);document.querySelector("#diary-list").innerHTML=a.map(x=>card("Запись",fmt(x.date),`${x.body?`<p>${esc(x.body)}</p>`:""}`,"diary",x.id)).join("")||"<p class='muted'>Записей за этот период нет.</p>";}
async function renderTraits(){const a=await all("traits");let html=a.length?`<div class="table-wrap"><table class="traits-table"><thead><tr><th>Сфера</th>${PHASES.map(k=>`<th>${PHASE_LABELS[k]}</th>`).join("")}<th>Действия</th></tr></thead><tbody>${a.map(x=>`<tr><th>${esc(x.topic)}</th>${PHASES.map(k=>`<td>${esc(x[k]||"")}</td>`).join("")}<td><div class="row-actions"><button type="button" class="secondary" data-edit-trait="${x.id}">Редактировать</button><button type="button" class="secondary" data-delete-trait="${x.id}">Удалить</button></div></td></tr>`).join("")}</tbody></table></div>`:"<p class='muted'>Добавь первую сферу наблюдения.</p>";document.querySelector("#trait-list").innerHTML=html;}
