// Menstrual-cycle tracker. Calendar interactions are delegated directly to the calendar.
let cycleMonth=new Date();cycleMonth.setDate(1);
const dayMs=86400000;
function dateKey(d){return `${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,"0")}-${String(d.getDate()).padStart(2,"0")}`;}
function dateFromKey(s){const m=String(s||"").match(/^(\d{4})-(\d{2})-(\d{2})$/);if(!m)return new Date(NaN);return new Date(Number(m[1]),Number(m[2])-1,Number(m[3]),12);}
function validDateKey(s){const d=dateFromKey(s);return !Number.isNaN(d.getTime())&&dateKey(d)===s;}
function shiftDate(d,n){const x=new Date(d);x.setDate(x.getDate()+n);return x;}
function dayDiff(a,b){return Math.round((dateFromKey(b)-dateFromKey(a))/dayMs);}
function recordDate(r){return String(r?.date||"").slice(0,10);}
function cycleInfo(records){
 const days=new Set(records.filter(x=>x?.type==="period"&&validDateKey(recordDate(x))).map(recordDate));
 const starts=[...days].filter(d=>!days.has(dateKey(shiftDate(dateFromKey(d),-1)))).sort();
 const intervals=[];for(let i=1;i<starts.length;i++){const n=dayDiff(starts[i-1],starts[i]);if(n>=10&&n<=90)intervals.push(n);}
 const avg=intervals.length?Math.round(intervals.slice(-6).reduce((a,b)=>a+b,0)/Math.min(6,intervals.length)):null;
 const durationSamples=starts.map(st=>{let n=0;while(days.has(dateKey(shiftDate(dateFromKey(st),n)))&&n<15)n++;return n;}).filter(n=>n>0);
 const periodLength=durationSamples.length?Math.max(1,Math.min(10,Math.round(durationSamples.reduce((a,b)=>a+b,0)/durationSamples.length))):5;
 return {days,starts,avg,periodLength,intervals};
}
function cycleForecast(info){if(!info.starts.length||!info.avg)return [];const out=[];let next=dateFromKey(info.starts[info.starts.length-1]);for(let i=0;i<12;i++){next=shiftDate(next,info.avg);out.push({start:dateKey(next),end:dateKey(shiftDate(next,info.periodLength-1)),ovulation:dateKey(shiftDate(next,-14))});}return out;}
function phaseForDate(key,info,forecast){const candidates=[...info.starts.map(start=>({start,ovulation:info.avg?dateKey(shiftDate(dateFromKey(start),info.avg-14)):""})),...forecast.map(x=>({start:x.start,ovulation:x.ovulation}))].filter(x=>x.start<=key).sort((a,b)=>b.start.localeCompare(a.start));if(!candidates.length)return "";const c=candidates[0],day=dayDiff(c.start,key)+1;if(day<=info.periodLength)return "Месячные";if(key===c.ovulation)return "Овуляция*";if(c.ovulation&&key<c.ovulation)return "Фолликулярная";if(c.ovulation&&key>c.ovulation)return "Лютеиновая";return "";}
function fertilityEstimate(key,info,forecast){const cycles=[...info.starts.map(start=>({start,ovulation:info.avg?dateKey(shiftDate(dateFromKey(start),info.avg-14)):""})),...forecast.map(x=>({start:x.start,ovulation:x.ovulation}))].filter(x=>x.start<=key&&x.ovulation).sort((a,b)=>b.start.localeCompare(a.start));if(!cycles.length)return {label:"Недостаточно данных для оценки",detail:"Нужны даты начала нескольких менструаций."};const d=dayDiff(cycles[0].ovulation,key);if(d>=-5&&d<=-4)return {label:"Повышенная вероятность",detail:"Предполагаемое фертильное окно."};if(d>=-3&&d<=-2)return {label:"Высокая вероятность",detail:"День близок к предполагаемой овуляции."};if(d>=-1&&d<=0)return {label:"Наиболее высокая вероятность",detail:"Предполагаемый день перед овуляцией или день овуляции."};if(d===1)return {label:"Вероятность снижается",detail:"После овуляции вероятность обычно снижается."};return {label:"Ниже по календарной оценке",detail:"Это не означает нулевой вероятности: овуляция может смещаться."};}
function cycleSymptoms(){const fallback=["Хорошее самочувствие","Плохое самочувствие","Боль","Усталость","Вздутие","Чувствительность груди","Тревожность","Раздражительность"];try{const a=JSON.parse(localStorage.getItem("my-state-cycle-symptoms")||"null");return Array.isArray(a)?[...new Set(a.filter(x=>typeof x==="string"&&x.trim()).map(x=>x.trim()))]:fallback;}catch{return fallback;}}
