 const records=await all("cycle"),safe=records.filter(x=>x&&typeof x==="object"),info=cycleInfo(safe),forecast=cycleForecast(info),lang=localStorage.getItem("my-state-language")||"ru",locale=lang==="pl"?"pl-PL":lang==="en"?"en-GB":"ru-RU";
