function sleepExportRows(records){if(!records.length)return [];const byDate=new Map(records.map(x=>[x.date,x]));const dates=records.map(x=>x.date).filter(Boolean).sort();const start=new Date(dates[0]+"T12:00:00"),end=new Date(localDate()+"T12:00:00"),out=[];for(let d=new Date(start);d<=end;d.setDate(d.getDate()+1)){const key=d.toISOString().slice(0,10),item=byDate.get(key);out.push(item||{date:key,bed:"23:00",wake:"07:00",wakeIntervals:[],dream:"",note:""});}return out;}
