async function renderIdeas(){const a=await all("criticality");document.querySelector("#idea-list").innerHTML=a.map(x=>`<article class="entry"><div class="entry-title">${esc(x.idea)}</div><small>${esc(x.date)} · Фаза создания: ${esc(x.phase||"Фаза не указана")}</small><p>Последняя оценка: ${esc(assessmentLabel(x.assessment))}</p>${(x.assessmentHistory||[]).map(h=>`<p class="small">${fmt(h.date)} · ${esc(h.assessment)} · Фаза: ${esc(h.phase||"Фаза не указана")}</p>`).join("")}<button class="secondary" data-assess="${x.id}">Изменить оценку</button><button type="button" class="delete" data-delete-idea="${x.id}">Удалить идею</button><div class="assessment-editor" id="assessment-${x.id}" hidden><label>Новая оценка<select><option value="">Выбрать оценку</option><option value="reasonable">Адекватная</option><option value="questionable">Сомнительная</option><option value="unreasonable">Неадекватная</option><option value="defer">Отложить до повторной оценки</option></select></label><button class="primary" data-save-assess="${x.id}">Сохранить оценку</button></div></article>`).join("")||"<p class='muted'>Идей пока нет.</p>";}
function isReasonableAssessment(value){return ["reasonable","Адекватная","Zasadna","Reasonable"].includes(String(value||"").trim());}
function assessmentLabel(value){return ({reasonable:"Адекватная",questionable:"Сомнительная",unreasonable:"Неадекватная",defer:"Отложить до повторной оценки"})[value]||value||"Пока не оценивалась";}
async function syncGoals(){const ideas=await all("criticality"),goals=await all("goals");for(const idea of ideas){if(isReasonableAssessment(idea.assessment)&&!idea.goalDeleted&&!goals.some(g=>g.ideaId===idea.id)){await add("goals",{ideaId:idea.id,title:idea.idea,createdAt:idea.date||new Date().toISOString(),subgoals:[]});}}for(const goal of goals){const idea=ideas.find(i=>i.id===goal.ideaId);if(idea&&!isReasonableAssessment(idea.assessment))await remove("goals",goal.id);} }
async function renderGoals(){
 await syncGoals();const goals=await all("goals");
 const legacyCurrency=localStorage.getItem("my-state-currency")||"EUR";for(const g of goals){if(!g.currency){g.currency=legacyCurrency;await put("goals",g);}}
 document.querySelector("#goals-list").innerHTML=goals.map(g=>{
  const subs=g.subgoals||[],cur=g.currency||"EUR",days=g.daysOverride??subs.reduce((n,s)=>n+(Number(s.days)||0),0),cost=g.costOverride??subs.reduce((n,s)=>n+(Number(s.cost)||0),0),created=(g.created||g.createdAt||"").slice(0,10)||"Дата не указана",achieved=subs.length>0&&subs.every(s=>s.completed===true||!!s.doneDate);
  return `<article class="entry goal-entry"><details class="goal-details"><summary><span class="goal-title">${esc(g.title)}</span>${achieved?`<span class="goal-achieved">Достигнута</span>`:""}<small> · ${esc(created)}</small><button type="button" class="secondary goal-edit-icon" data-edit-goal="${g.id}" aria-label="Изменить цель" title="Изменить цель">✎</button><span class="goal-totals">Суммарный срок: ${days} дней<br>Суммарная стоимость: ${money(cost,cur)}</span></summary>
  <label class="goal-currency">Валюта цели<select data-goal-currency="${g.id}"><option value="EUR" ${cur==="EUR"?"selected":""}>EUR (€)</option><option value="PLN" ${cur==="PLN"?"selected":""}>PLN (zł)</option><option value="RUB" ${cur==="RUB"?"selected":""}>RUB (₽)</option></select></label>
  ${subs.map((sub,i)=>`<div class="subgoal"><div class="sub-edit-row"><b>${esc(sub.title)}</b><button type="button" class="secondary goal-edit-icon" data-edit-sub="${g.id}:${i}" aria-label="Изменить подцель" title="Изменить подцель">✎</button><button type="button" class="delete" data-delete-subgoal="${g.id}:${i}">Удалить</button></div><label class="subgoal-done"><input type="checkbox" data-sub-done="${g.id}:${i}" ${sub.completed===true||sub.doneDate?"checked":""}> Выполнено</label><p>Срок: ${sub.days||0} дней<br>Исполнение: ${esc(sub.doneDate||"Не указано")}<br>Стоимость: ${money(sub.cost,cur)}<br>Плановая дата: ${esc(sub.due||"Не указана")}</p></div>`).join("")}
  <button type="button" class="secondary add-subgoal-toggle" data-add-subgoal="${g.id}">Добавить подцель</button><button type="button" class="delete" data-delete-goal="${g.id}">Удалить цель</button><form class="subgoal-form" data-goal="${g.id}" hidden><label>Название подцели<input name="title" required></label><div class="two"><label>Срок (дней)<input name="days" type="number" min="0" step="1" value="0"></label><label>Стоимость (${currencySymbol(cur)})<input name="cost" type="number" min="0" step="0.01" value="0"></label></div><label>Дата исполнения<input name="due" type="date"></label><button class="primary">Сохранить подцель</button></form></details></article>`;
 }).join("")||"<p class='muted'>Пока нет целей. Они появятся здесь после оценки идеи как «Адекватная».</p>";
}

