// Excel-compatible XML workbook with one worksheet per app section; opens in Excel without external libraries or internet.
function xml(v){return String(v??"").replace(/&/g,"&amp;").replace(/</g,"&lt;").replace(/>/g,"&gt;").replace(/"/g,"&quot;").replace(/'/g,"&apos;");}
document.querySelector("#export-all").onclick=async()=>{let sheets="";for(const key of ["meds","mood","sleep","diary","traits","medLogs","criticality","goals","cycle"]){let records=await all(key);if(key==="sleep")records=sleepExportRows(records);if(key==="goals")records=records.flatMap(x=>(x.subgoals||[]).map(s=>({...x,...s})));if(key==="medLogs"){const meds=await all("meds");window.__medExportCache=meds;const groups={};for(const l of records){const k=[l.medId,l.date,l.period].join("|");if(!groups[k])groups[k]={...l,count:0};groups[k].count++;}records=Object.values(groups);}const rows=[exports[key].headers.map(v=>translateString(v,LANG[localStorage.getItem("my-state-language")||"ru"]||{})),...records.map(exports[key].map)];sheets+=`<Worksheet ss:Name="${xml(translateString(({meds:"Лекарства",mood:"Настроение",sleep:"Сон",diary:"Дневник",traits:"Фазы",medLogs:"Приём",criticality:"Идеи",goals:"Цели",cycle:"Цикл"})[key],LANG[localStorage.getItem("my-state-language")||"ru"]||{}))}"><Table>${rows.map(r=>`<Row>${r.map(v=>`<Cell><Data ss:Type="String">${xml(v)}</Data></Cell>`).join("")}</Row>`).join("")}</Table></Worksheet>`;}const indexSheet=`<Worksheet ss:Name="Содержание"><Table><Row><Cell><Data ss:Type="String">${xml(translateString("Разделы книги",LANG[localStorage.getItem("my-state-language")||"ru"]||{}))}</Data></Cell></Row>${["Лекарства","Настроение","Сон","Дневник","Фазы","Приём","Идеи","Цели","Цикл"].map(n=>`<Row><Cell><Data ss:Type="String">${xml(translateString(n,LANG[localStorage.getItem("my-state-language")||"ru"]||{}))}</Data></Cell></Row>`).join("")}</Table></Worksheet>`;const book=`<?xml version="1.0"?><Workbook xmlns="urn:schemas-microsoft-com:office:spreadsheet" xmlns:ss="urn:schemas-microsoft-com:office:spreadsheet">${indexSheet}${sheets}</Workbook>`;download("moe-sostoyanie-excel.xls",book,"application/vnd.ms-excel;charset=utf-8");};
document.querySelector("#backup").onclick=async()=>{
 try{const data={format:"my-state-backup",version:5,exportedAt:new Date().toISOString(),emergencyContacts:readContacts(),customMoodIndicators:customMoodNames(),cycleSymptoms:cycleSymptoms()};for(const s of STORES)data[s]=await all(s);
 download("my-state-backup.json",JSON.stringify(data,null,2),"application/json;charset=utf-8");
 }catch(err){console.error(err);document.querySelector("#export-status").textContent="Не удалось создать резервную копию: "+err.message;}
};
document.querySelector("#restore-backup").addEventListener("change",async e=>{
 const file=e.target.files?.[0];if(!file)return;
 try{
  const raw=(await file.text()).replace(/^\uFEFF/,"");let parsed=JSON.parse(raw);
  // Accept backups from earlier app releases, including exports with a data wrapper.
  const data=parsed?.data&&typeof parsed.data==="object"?{...parsed,...parsed.data}:parsed;
  const hasStore=STORES.some(s=>Array.isArray(data?.[s]));
  if(!data||typeof data!=="object"||(!hasStore&&data.format!=="my-state-backup")||(data.format&&data.format!=="my-state-backup"))throw new Error("Неверный формат резервной копии. Выбери JSON-файл, созданный кнопкой «Скачать резервную копию».");
  for(const s of STORES){if(data[s]!==undefined&&!Array.isArray(data[s]))throw new Error("Повреждён раздел "+s);if((data[s]||[]).some(item=>!item||typeof item!=="object"||Array.isArray(item)||!("id" in item)))throw new Error("Повреждённая запись в разделе "+s);}

  if(!confirm(trUI("Восстановление заменит все текущие записи данными из файла. Продолжить?")))return;
  await new Promise((resolve,reject)=>{
   const tx=db.transaction(STORES,"readwrite");
   for(const s of STORES){const os=tx.objectStore(s);os.clear();for(const item of (data[s]||[]))os.put(item);}
   tx.oncomplete=resolve;tx.onerror=()=>reject(tx.error);tx.onabort=()=>reject(tx.error||new Error("Транзакция прервана"));
  });
  if(Array.isArray(data.customMoodIndicators))localStorage.setItem(MOOD_CUSTOM_KEY,JSON.stringify(data.customMoodIndicators.filter(x=>typeof x==="string")));if(Array.isArray(data.cycleSymptoms))localStorage.setItem("my-state-cycle-symptoms",JSON.stringify(data.cycleSymptoms.filter(x=>typeof x==="string")));if(Array.isArray(data.emergencyContacts))saveContacts(data.emergencyContacts.filter(c=>c&&typeof c==="object").map(c=>({name:String(c.name||""),phone:String(c.phone||"")})));
  renderContacts();await refreshAll();alert(trUI("Данные восстановлены."));
 }catch(err){console.error(err);alert("Не удалось восстановить копию: "+err.message);}
 finally{e.target.value="";}
});

// Emergency contacts are stored only in this browser. tel: links hand off to the phone app.
const CONTACTS_KEY="my-state-emergency-contacts";
function readContacts(){try{const a=JSON.parse(localStorage.getItem(CONTACTS_KEY)||"[]");return Array.isArray(a)?a:[];}catch{return [];}}
function saveContacts(items){localStorage.setItem(CONTACTS_KEY,JSON.stringify(items));}
function renderContacts(){const host=document.querySelector("#emergency-contacts");if(!host)return;const items=readContacts();host.innerHTML=items.map((c,i)=>`<div class="contact-row" data-contact-row="${i}"><input class="contact-name" aria-label="Имя контакта" value="${esc(c.name||"")}" readonly><a class="contact-phone" href="tel:${esc((c.phone||"").replace(/[^+0-9*#]/g,""))}">${esc(c.phone||"Номер телефона")}</a><button type="button" class="secondary contact-edit" data-contact-edit="${i}" aria-label="Редактировать контакт">✎</button><button type="button" class="delete contact-delete" data-contact-delete="${i}" aria-label="Удалить контакт">×</button></div>`).join("");}
document.querySelector("#add-contact").addEventListener("click",()=>{const items=readContacts();items.push({name:"",phone:""});saveContacts(items);renderContacts();const row=document.querySelector(`[data-contact-row="${items.length-1}"]`);row.innerHTML=`<input class="contact-name" aria-label="Имя контакта" placeholder="Имя"><input class="contact-phone-input" type="tel" aria-label="Номер телефона" placeholder="Номер телефона"><button type="button" class="secondary" data-contact-save="${items.length-1}">✓</button>`;row.querySelector(".contact-name").focus();});
document.querySelector("#emergency-contacts").addEventListener("click",e=>{const edit=e.target.closest("[data-contact-edit]");if(edit){const i=Number(edit.dataset.contactEdit),c=readContacts()[i],row=edit.closest(".contact-row");row.innerHTML=`<input class="contact-name" aria-label="Имя контакта" value="${esc(c.name||"")}" placeholder="Имя"><input class="contact-phone-input" type="tel" aria-label="Номер телефона" value="${esc(c.phone||"")}" placeholder="Номер телефона"><button type="button" class="secondary" data-contact-save="${i}">✓</button>`;row.querySelector(".contact-name").focus();return;}const save=e.target.closest("[data-contact-save]");if(save){const i=Number(save.dataset.contactSave),row=save.closest(".contact-row"),items=readContacts();items[i]={name:row.querySelector(".contact-name").value.trim(),phone:row.querySelector(".contact-phone-input").value.trim()};saveContacts(items);renderContacts();return;}const del=e.target.closest("[data-contact-delete]");if(del){const i=Number(del.dataset.contactDelete),items=readContacts();if(confirm(trUI("Удалить контакт?"))){items.splice(i,1);saveContacts(items);renderContacts();}}});
renderContacts();

// Home shortcuts control which section tabs are pinned. Export is always available.
const PIN_KEYS=["mood","sleep","cycle","meds","diary","criticality","goals","personality","proscons","lists"];
function applyPinnedTabs(){
 const saved=JSON.parse(localStorage.getItem("my-state-pinned")||"null")||Object.fromEntries(PIN_KEYS.map(k=>[k,true]));
 document.querySelectorAll("[data-pin]").forEach(c=>c.checked=saved[c.dataset.pin]!==false);
 document.querySelectorAll(".tab[data-view]").forEach(t=>{const k=t.dataset.view;t.hidden=PIN_KEYS.includes(k)&&saved[k]===false;});
 localStorage.setItem("my-state-pinned",JSON.stringify(saved));
}
document.querySelectorAll("[data-pin]").forEach(c=>c.addEventListener("change",()=>{
 const saved=JSON.parse(localStorage.getItem("my-state-pinned")||"{}");saved[c.dataset.pin]=c.checked;localStorage.setItem("my-state-pinned",JSON.stringify(saved));applyPinnedTabs();
}));
applyPinnedTabs();

// Currency affects display only; stored numeric amounts are never recalculated.
const CURRENCIES={EUR:{symbol:"€",label:"евро"},PLN:{symbol:"zł",label:"злотых"},RUB:{symbol:"₽",label:"рублей"}};
function currencySymbol(currency="EUR"){return (CURRENCIES[currency]||CURRENCIES.EUR).symbol;}
function money(value,currency="EUR"){return `${Number(value||0).toFixed(2)} ${currencySymbol(currency)}`;}
