const originalText=new WeakMap(),originalAttrs=new WeakMap();
function translateString(source,dict){
 if(!source)return source;
 const trimmed=source.trim();if(dict[trimmed])return source.replace(trimmed,dict[trimmed]);
 let out=source;
 const keys=Object.keys(dict).sort((a,b)=>b.length-a.length);
 for(const k of keys){
  if(k.length>1&&out.includes(k)){
   const escaped=k.replace(/[.*+?^${}()|[\]\\]/g,"\\$&");
   const re=new RegExp("(^|[^\\p{L}\\p{N}])("+escaped+")(?=$|[^\\p{L}\\p{N}])","giu");
   out=out.replace(re,(_m,prefix)=>prefix+dict[k]);
  }
 }
 return out;
}
function trUI(value){const lang=localStorage.getItem("my-state-language")||"ru";return lang==="ru"?value:translateString(value,LANG[lang]||{});}
function applyLanguage(lang){
 const dict=LANG[lang]||{};document.documentElement.lang=lang;
 document.querySelectorAll("[data-lang]").forEach(b=>b.classList.toggle("active",b.dataset.lang===lang));
 const walker=document.createTreeWalker(document.body,NodeFilter.SHOW_TEXT);
 while(walker.nextNode()){
  const n=walker.currentNode;
  if(n.parentElement?.closest("script,style"))continue;
  if(!originalText.has(n))originalText.set(n,n.nodeValue);
  n.nodeValue=lang==="ru"?originalText.get(n):translateString(originalText.get(n),dict);
 }
 document.querySelectorAll("input[placeholder],textarea[placeholder],button[title],button[aria-label]").forEach(el=>{
  ["placeholder","title","aria-label"].forEach(attr=>{if(!el.hasAttribute(attr))return;let vals=originalAttrs.get(el);if(!vals){vals={};originalAttrs.set(el,vals);}if(!(attr in vals))vals[attr]=el.getAttribute(attr);el.setAttribute(attr,lang==="ru"?vals[attr]:translateString(vals[attr],dict));});
 });
}
document.querySelectorAll("[data-lang]").forEach(b=>b.addEventListener("click",()=>{localStorage.setItem("my-state-language",b.dataset.lang);applyLanguage(b.dataset.lang);}));
const languageObserver=new MutationObserver(()=>{const lang=localStorage.getItem("my-state-language")||"ru";applyLanguage(lang);});
languageObserver.observe(document.body,{childList:true,subtree:true});
// One-time age and terms confirmation. Stored locally on this device.
const consentOverlay=document.querySelector("#consent-overlay"),ageBox=document.querySelector("#age-confirm"),policyBox=document.querySelector("#policy-confirm"),acceptButton=document.querySelector("#consent-accept");
function updateConsentButton(){acceptButton.disabled=!(ageBox.checked&&policyBox.checked);}
ageBox.addEventListener("change",updateConsentButton);policyBox.addEventListener("change",updateConsentButton);
acceptButton.addEventListener("click",()=>{if(!(ageBox.checked&&policyBox.checked))return;localStorage.setItem("my-state-consent-v1",JSON.stringify({age18:true,accepted:true,acceptedAt:new Date().toISOString()}));consentOverlay.hidden=true;});
if(!localStorage.getItem("my-state-consent-v1"))consentOverlay.hidden=false;


document.querySelector("#proscons-form").addEventListener("submit",async e=>{e.preventDefault();const f=e.currentTarget,title=String(new FormData(f).get("title")||"").trim();if(!title)return;const button=f.querySelector("button[type=submit]");if(button)button.disabled=true;try{await add("proscons",{title,pros:[],cons:[]});f.reset();await renderProsCons();}catch(err){console.error("Pros/cons topic save failed",err);alert(trUI("Не удалось сохранить тему."));}finally{if(button)button.disabled=false;}});
document.querySelector("#planner-list-form").addEventListener("submit",async e=>{e.preventDefault();const f=e.currentTarget,v=formObject(f),title=(v.title||"").trim();if(!title)return;const button=f.querySelector("button[type=submit]");if(button)button.disabled=true;try{await add("plannerLists",{title,due:v.due||"",items:[]});f.reset();await renderPlannerLists();await renderPlannerCalendar();}catch(err){console.error("Planner list save failed",err);alert(trUI("Не удалось сохранить список."));}finally{if(button)button.disabled=false;}});
document.querySelector("#planner-lists").addEventListener("submit",async e=>{
 const f=e.target.closest("form[data-plan-add]");if(!f)return;e.preventDefault();
 const submit=f.querySelector("button[type=submit],button:not([type])"),id=Number(f.dataset.planAdd),value=f.elements.text.value.trim();if(!value)return;
 if(submit)submit.disabled=true;
 try{const row=(await all("plannerLists")).find(x=>x.id===id);if(!row)return;row.items=[...(row.items||[]),{text:value,done:false}];await put("plannerLists",row);await renderPlannerLists();await renderPlannerCalendar();if(!document.querySelector("#planner-day-modal").hidden&&row.due)await openPlannerDay(row.due);}
 catch(err){console.error("Planner item save failed",err);alert(trUI("Не удалось сохранить позицию."));}
 finally{if(submit)submit.disabled=false;}
});
document.addEventListener("change",async e=>{const c=e.target.closest("[data-plan-done]");if(!c)return;const [id,idx]=c.dataset.planDone.split("|").map(Number),row=(await all("plannerLists")).find(x=>x.id===id);if(!row||!row.items?.[idx])return;row.items[idx].done=c.checked;await put("plannerLists",row);await renderPlannerLists();await renderPlannerCalendar();if(!document.querySelector("#planner-day-modal").hidden){const day=document.querySelector("#planner-day-title").textContent;const date=row.due;if(date)await openPlannerDay(date);}});
document.addEventListener("click",async e=>{
 const pcAdd=e.target.closest("[data-pc-add]");if(pcAdd){const [id,key]=pcAdd.dataset.pcAdd.split("|"),row=(await all("proscons")).find(x=>x.id===Number(id)),value=prompt(trUI(key==="pros"?"Добавить плюс":"Добавить минус"));if(row&&value?.trim()){row[key]=[...(row[key]||[]),value.trim()];await put("proscons",row);await renderProsCons();}return;}
 const pcEdit=e.target.closest("[data-pc-edit]");if(pcEdit){const [id,key,idx]=pcEdit.dataset.pcEdit.split("|"),row=(await all("proscons")).find(x=>x.id===Number(id));if(!row)return;const value=prompt(trUI("Изменить запись"),row[key][Number(idx)]);if(value===null)return;if(!value.trim()){alert(trUI("Текст не может быть пустым."));return;}row[key][Number(idx)]=value.trim();await put("proscons",row);await renderProsCons();return;}
 const pcDel=e.target.closest("[data-pc-del]");if(pcDel){const [id,key,idx]=pcDel.dataset.pcDel.split("|"),row=(await all("proscons")).find(x=>x.id===Number(id));if(row&&confirm(trUI("Удалить запись?"))){row[key].splice(Number(idx),1);await put("proscons",row);await renderProsCons();}return;}
 const pcRename=e.target.closest("[data-pc-rename]");if(pcRename){const row=(await all("proscons")).find(x=>x.id===Number(pcRename.dataset.pcRename));if(!row)return;const title=prompt(trUI("Название темы"),row.title);if(title?.trim()){row.title=title.trim();await put("proscons",row);await renderProsCons();}return;}
 const pcDelete=e.target.closest("[data-pc-delete]");if(pcDelete){const id=Number(pcDelete.dataset.pcDelete);if(confirm(trUI("Удалить тему вместе со всеми записями?"))){await remove("proscons",id);await renderProsCons();}return;}
 const plEdit=e.target.closest("[data-plan-edit]");if(plEdit){const [id,idx]=plEdit.dataset.planEdit.split("|").map(Number),row=(await all("plannerLists")).find(x=>x.id===id);if(!row)return;const text=prompt(trUI("Изменить позицию"),row.items[idx].text);if(text?.trim()){row.items[idx].text=text.trim();await put("plannerLists",row);await renderPlannerLists();await renderPlannerCalendar();}return;}
 const plDel=e.target.closest("[data-plan-del]");if(plDel){const [id,idx]=plDel.dataset.planDel.split("|").map(Number),row=(await all("plannerLists")).find(x=>x.id===id);if(row&&confirm(trUI("Удалить позицию?"))){row.items.splice(idx,1);await put("plannerLists",row);await renderPlannerLists();await renderPlannerCalendar();}return;}
 const plRename=e.target.closest("[data-plan-rename]");if(plRename){const row=(await all("plannerLists")).find(x=>x.id===Number(plRename.dataset.planRename));if(!row)return;const title=prompt(trUI("Название списка"),row.title);if(title===null)return;const due=prompt(trUI("Дата исполнения (ГГГГ-ММ-ДД), пусто — без даты"),row.due||"");if(due===null)return;row.title=title.trim()||row.title;row.due=due.trim();await put("plannerLists",row);await renderPlannerLists();await renderPlannerCalendar();return;}
 const plDelete=e.target.closest("[data-plan-delete]");if(plDelete){const id=Number(plDelete.dataset.planDelete);if(confirm(trUI("Удалить список вместе со всеми позициями?"))){await remove("plannerLists",id);await renderPlannerLists();await renderPlannerCalendar();}return;}
 const day=e.target.closest("[data-planner-day]");if(day){await openPlannerDay(day.dataset.plannerDay);return;}
});
document.querySelector("#planner-prev").addEventListener("click",()=>{plannerMonth=new Date(plannerMonth.getFullYear(),plannerMonth.getMonth()-1,1);renderPlannerCalendar();});
document.querySelector("#planner-next").addEventListener("click",()=>{plannerMonth=new Date(plannerMonth.getFullYear(),plannerMonth.getMonth()+1,1);renderPlannerCalendar();});
document.querySelector("#planner-day-close").addEventListener("click",()=>{document.querySelector("#planner-day-modal").hidden=true;});
document.querySelector("#planner-day-modal").addEventListener("click",e=>{if(e.target.id==="planner-day-modal")e.currentTarget.hidden=true;});

async function refreshAll(){await Promise.all([renderMeds(),renderMood(),renderSleep(),renderCycle(),renderDiary(),renderTraits(),renderIdeas(),renderGoals(),renderHomeMeds(),renderProsCons(),renderPlannerLists(),renderPlannerCalendar()]);}
(async()=>{db=await openDB();await initCycleStorage();document.querySelector('#mood-form [name="date"]').value=localDateTime();document.querySelector('#diary-form [name="date"]').value=localDateTime();document.querySelector('#sleep-form [name="date"]').value=localDate();document.querySelector('#sleep-form [name="bed"]').value="23:00";document.querySelector('#sleep-form [name="wake"]').value="07:00";document.querySelector('#idea-form [name="date"]').value=localDateTime();addWakeRow();await refreshAll();applyLanguage(localStorage.getItem("my-state-language")||"ru");})().catch(err=>{console.error(err);alert(trUI("Не удалось открыть локальную базу данных."));});
